<?php
namespace qqworld_collector\module\settings; use qqworld_collector\lib; class database extends lib { public function __construct() {} public function init() { if ($this->options->qc_database_sql_calc_found_rows) { add_filter( 'pre_get_posts', array($this, 'set_no_found_rows'), 10, 1 ); add_filter( 'posts_clauses', array($this, 'set_found_posts'), 10, 2 ); } } public function set_no_found_rows( \WP_Query $wp_query ) { $wp_query->set( 'no_found_rows', true ); } public function set_found_posts( $clauses, \WP_Query $wp_query ) { if ( $wp_query->is_singular() ) { return $clauses; } global $wpdb; $where = isset( $clauses[ 'where' ] ) ? $clauses[ 'where' ] : ''; $join = isset( $clauses[ 'join' ] ) ? $clauses[ 'join' ] : ''; $distinct = isset( $clauses[ 'distinct' ] ) ? $clauses[ 'distinct' ] : ''; $wp_query->found_posts = $wpdb->get_var( "SELECT $distinct COUNT(*) FROM {$wpdb->posts} $join WHERE 1=1 $where" ); $posts_per_page = ( ! empty( $wp_query->query_vars['posts_per_page'] ) ? absint( $wp_query->query_vars['posts_per_page'] ) : absint( get_option( 'posts_per_page' ) ) ); $wp_query->max_num_pages = ceil( $wp_query->found_posts / $posts_per_page ); return $clauses; } } ?>